import { useState, type ReactNode } from 'react';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

const ChevronDown = () => (
  <svg width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M6 9l6 6 6-6" />
  </svg>
);

// ---- AccordionItem ----

export type AccordionItemProps = {
  title: string;
  defaultOpen?: boolean;
  children: ReactNode;
  className?: string;
};

export function AccordionItem({ title, defaultOpen = false, children, className }: AccordionItemProps) {
  const [open, setOpen] = useState(defaultOpen);

  return (
    <div className={cn('accordion__item', open && 'accordion__item--open', className)}>
      <button
        type="button"
        className="accordion__trigger"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
      >
        {title}
        <span className="accordion__chevron"><ChevronDown /></span>
      </button>
      <div className="accordion__content-wrapper">
        <div className="accordion__content">
          <div className="accordion__content-inner">
            {children}
          </div>
        </div>
      </div>
    </div>
  );
}

// ---- Accordion ----

export type AccordionProps = {
  children: ReactNode;
  className?: string;
};

export function Accordion({ children, className }: AccordionProps) {
  return <div className={cn('accordion', className)}>{children}</div>;
}

/* -------------------------------------------------------------------------
   Accordion

   Collapsible content sections. Single or multiple open.
   All colors via semantic tokens. Spacing via token values.

   Parts: .accordion, .accordion__item, .accordion__trigger, .accordion__content
   ------------------------------------------------------------------------- */

.accordion {
  width: 100%;
}

.accordion__item {
  border-bottom: 1px solid var(--border);
}

.accordion__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-2, 8px);
  width: 100%;
  padding: var(--spacing-4, 16px) 0;
  border: none;
  background: none;
  font-family: inherit;
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-medium);
  line-height: 1.4;
  color: var(--foreground);
  text-align: left;
  text-decoration: none;
  cursor: pointer;
  transition: color 0.15s ease;
}

.accordion__trigger:hover {
  color: var(--muted-foreground);
}

.accordion__trigger:focus-visible {
  outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color);
  outline-offset: 2px;
  border-radius: 4px;
}

.accordion__chevron {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  color: var(--muted-foreground);
  transition: transform 0.3s cubic-bezier(0.19, 1, 0.22, 1);
}

.accordion__chevron svg {
  width: 100%;
  height: 100%;
}

.accordion__item--open .accordion__chevron {
  transform: rotate(180deg);
}

/* Content: animated height via grid */
.accordion__content-wrapper {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.3s cubic-bezier(0.19, 1, 0.22, 1);
}

.accordion__item--open .accordion__content-wrapper {
  grid-template-rows: 1fr;
}

.accordion__content {
  overflow: hidden;
  min-height: 0;
}

.accordion__content-inner {
  padding-bottom: var(--spacing-4, 16px);
  font-family: inherit;
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
  color: var(--muted-foreground);
}

@media (prefers-reduced-motion: reduce) {
  .accordion__content-wrapper,
  .accordion__chevron {
    transition-duration: 0ms;
  }
}
